window.VO = [{"id":"n01","text":"You're the only witness. Again.","at":0.24,"t0":0.12,"t1":1.938},{"id":"n02","text":"Watch his face.","at":4.276,"t0":2.138,"t1":3.229},{"id":"n03","text":"This time, he's one of these six, and whoever you pick goes to prison.","at":9.898,"t0":4.949,"t1":10.04},{"id":"n04","text":"Out of ten, how sure are you?","at":22.98,"t0":11.49,"t1":14.035},{"id":"o01","text":"So? Which one?","at":31.17,"t0":15.585,"t1":16.676},{"id":"o02","text":"Good. That's him.","at":36.452,"t0":18.226,"t1":19.317},{"id":"n05","text":"He's a drawing, so he can't see what you picked.","at":39.934,"t0":19.967,"t1":23.603},{"id":"n06","text":"So here's the real answer.","at":47.908,"t0":23.954,"t1":25.772},{"id":"n07","text":"It's number three.","at":51.784,"t0":25.892,"t1":26.983},{"id":"n08","text":"Of course it is. Look at him.","at":54.866,"t0":27.433,"t1":29.978},{"id":"n09","text":"Now how sure are you?","at":60.456,"t0":30.228,"t1":32.046},{"id":"n10","text":"It isn't number three.","at":65.992,"t0":32.996,"t1":34.451},{"id":"n11","text":"I made that up.","at":69.402,"t0":34.701,"t1":36.156},{"id":"n12","text":"And whoever you picked is still going to prison.","at":73.41,"t0":36.705,"t1":39.978},{"id":"n13","text":"You still know how sure you were, because I asked.","at":81.456,"t0":40.728,"t1":44.364},{"id":"n14","text":"If nobody asks, one good and you'd swear you were sure from the start.","at":89.23,"t0":44.615,"t1":49.706},{"id":"n15","text":"In America, police told a real witness she'd picked the same man again, and she thought,","at":100.31,"t0":50.155,"t1":55.973},{"id":"n15b","text":"Bingo. I did it right.","at":112.248,"t0":56.124,"t1":57.942},{"id":"n16","text":"It was the wrong man, and Ronald Cotton lost more than ten years.","at":116.984,"t0":58.492,"t1":63.219},{"id":"n17","text":"He really is one of these six.","at":127.838,"t0":63.919,"t1":66.464},{"id":"n18","text":"I could tell you which, but you'd believe me.","at":133.53,"t0":66.765,"t1":70.038},{"id":"o03","text":"So? Which one?","at":140.774,"t0":70.387,"t1":71.478},{"id":"o04","text":"Good. That's him.","at":146.456,"t0":73.228,"t1":74.319}];
